diff --git a/internal/index/zstd_missing_test.go b/internal/index/zstd_missing_test.go
index d587e208..69259497 100644
--- a/internal/index/zstd_missing_test.go
+++ b/internal/index/zstd_missing_test.go
@@ -2,6 +2,7 @@ package index

 import (
 	"bytes"
+	"fmt"
 	"os"
 	"path/filepath"
 	"runtime"
@@ -218,3 +219,29 @@ func TestDeferredRolloutReadWhenFingerprintHadZstd(t *testing.T) {
 		t.Fatal("rollout still held as waiting after it was read")
 	}
 }
+
+// On a first build big enough to publish its newest slice early, the rollouts
+// waiting for zstd are still held as waiting once the build ends; the early
+// publish must not drain the list the full build commits (#5110).
+func TestFirstBuildKeepsDeferredAcrossNewestFirstPublish(t *testing.T) {
+	tmp := hermeticIndexEnv(t)
+	_, _, zst := zstdStubRollouts(t, tmp, "zstd-big-thread")
+	dir := filepath.Join(os.Getenv("DEJA_CODEX_ROOT"), "sessions", "2026", "07", "30")
+	for i := 0; i < partialPublishFrom+10; i++ {
+		id := fmt.Sprintf("big-%04d", i)
+		write(t, filepath.Join(dir, "rollout-2026-07-30T00-00-00-"+id+".jsonl"),
+			strings.ReplaceAll(codexRolloutHead, "cx-1", id))
+	}
+
+	idx := filepath.Join(tmp, "idx")
+	if err := Ensure(idx, "", false, nil); err != nil {
+		t.Fatal(err)
+	}
+	m, err := readManifest(idx)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if _, waiting := m.Deferred[zst]; !waiting {
+		t.Fatalf("first build left Deferred empty (%d entries), want the compressed rollout", len(m.Deferred))
+	}
+}
diff --git a/internal/sources/diag.go b/internal/sources/diag.go
index 8f013da7..cd1c9c7d 100644
--- a/internal/sources/diag.go
+++ b/internal/sources/diag.go
@@ -79,6 +79,14 @@ func DiagNoZstdPaths() map[string]bool {
 	return maps.Clone(diagZstdMissing)
 }

+// DiagRestoreNoZstd puts back paths DiagSnapshot cleared, for a write that
+// must not consume them before the pass that read them is done.
+func DiagRestoreNoZstd(paths map[string]bool) {
+	diagMu.Lock()
+	defer diagMu.Unlock()
+	maps.Copy(diagZstdMissing, paths)
+}
+
 // DiagMalformedCounts returns the malformed-line counts accumulated so far
 // without clearing them. The index narrates each store as it lands, which is
 // before the manifest fold that drains these counters (#1993).
diff --git a/internal/sources/diag_zstd_test.go b/internal/sources/diag_zstd_test.go
new file mode 100644
index 00000000..7c6a1ccf
--- /dev/null
+++ b/internal/sources/diag_zstd_test.go
@@ -0,0 +1,18 @@
+package sources
+
+import "testing"
+
+func TestDiagRestoreNoZstd(t *testing.T) {
+	DiagSnapshot()
+	diagNoZstd("a")
+	got := DiagNoZstdPaths()
+	DiagSnapshot()
+	if len(DiagNoZstdPaths()) != 0 {
+		t.Fatal("snapshot kept the paths")
+	}
+	DiagRestoreNoZstd(got)
+	if !DiagNoZstdPaths()["a"] {
+		t.Fatal("path not restored")
+	}
+	DiagSnapshot()
+}

