diff --git a/internal/viewer/static/theme.js b/internal/viewer/static/theme.js
new file mode 100644
index 0000000..2c7ea94
--- /dev/null
+++ b/internal/viewer/static/theme.js
@@ -0,0 +1,51 @@
+// SPDX-License-Identifier: Apache-2.0
+// Copyright 2026 alibaba/open-code-review Contributors
+
+// Light/dark theme switch. The stylesheet keys its dark palette off
+// data-theme on <html>; this script picks the initial value (saved choice,
+// else the OS preference) and wires up the header toggle button.
+(() => {
+    const KEY = "ocr-theme";
+    const root = document.documentElement;
+    const read = () => {
+        try {
+            return localStorage.getItem(KEY);
+        } catch (e) {
+            return null;
+        }
+    };
+    const initial = () => {
+        const saved = read();
+        if (saved === "light" || saved === "dark") return saved;
+        return window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
+    };
+    const apply = (theme) => {
+        root.setAttribute("data-theme", theme);
+        const btn = document.getElementById("theme-toggle");
+        if (!btn) return;
+        const next = theme === "dark" ? "light" : "dark";
+        btn.setAttribute("aria-label", "Switch to " + next + " mode");
+        btn.setAttribute("title", "Switch to " + next + " mode");
+        btn.textContent = theme === "dark" ? "\u2600" : "\u263E";
+    };
+    apply(initial());
+    const bind = () => {
+        const btn = document.getElementById("theme-toggle");
+        if (!btn) return;
+        apply(root.getAttribute("data-theme"));
+        btn.addEventListener("click", () => {
+            const next = root.getAttribute("data-theme") === "dark" ? "light" : "dark";
+            apply(next);
+            try {
+                localStorage.setItem(KEY, next);
+            } catch (e) {
+                // Storage can be blocked; the choice then lasts for this page only.
+            }
+        });
+    };
+    if (document.readyState === "loading") {
+        document.addEventListener("DOMContentLoaded", bind);
+    } else {
+        bind();
+    }
+})();
