+// limitations under the License.
+
+package llminternal
+
+import (
+	"iter"
+	"net"
+	"strings"
+	"sync/atomic"
+	"testing"
+	"time"
+
+	"github.com/gorilla/websocket"
+
+	"google.golang.org/adk/v2/agent"
+	"google.golang.org/adk/v2/model"
+	"google.golang.org/adk/v2/session"
+	"google.golang.org/adk/v2/tool"
+)
+
+// TestRunLive_DropWhileToolRuns checks that a resumable drop while a tool is
+// running is handled like the same drop with no tool running: the flow
+// reconnects and delivers the function response on the new connection.
+func TestRunLive_DropWhileToolRuns(t *testing.T) {
+	const toolCall = `{"toolCall":{"functionCalls":[{"id":"c1","name":"slow_job","args":{}}]}}`
+	tests := []struct {
+		name string
+		drop func(conn *websocket.Conn)
+	}{
+		{"hard close", func(*websocket.Conn) {}},
+		{"tcp reset", func(conn *websocket.Conn) {
+			if tcp, ok := conn.NetConn().(*net.TCPConn); ok {
+				_ = tcp.SetLinger(0)
+			}
+		}},
+		{"close frame 1008", func(conn *websocket.Conn) {
+			_ = conn.WriteMessage(websocket.CloseMessage, websocket.FormatCloseMessage(websocket.ClosePolicyViolation, "policy"))
+		}},
+	}
+	for _, tc := range tests {
+		t.Run(tc.name, func(t *testing.T) {
+			var toolResponseOnConn2 atomic.Bool
+			client, _ := startFakeLiveServer(t, func(connNum int, conn *websocket.Conn) {
+				if connNum == 1 {
+					if err := conn.WriteMessage(websocket.TextMessage, []byte(toolCall)); err != nil {
+						return
+					}
+					time.Sleep(50 * time.Millisecond) // the tool is still running
+					tc.drop(conn)
+					return
+				}
+				_ = conn.SetReadDeadline(time.Now().Add(2 * time.Second))
+				for {
+					_, msg, err := conn.ReadMessage()
+					if err != nil {
+						break
+					}
+					if strings.Contains(string(msg), "slow_job") {
+						toolResponseOnConn2.Store(true)
+						break
+					}
+				}
+				_ = conn.SetReadDeadline(time.Time{})
+				_ = conn.WriteMessage(websocket.TextMessage, []byte(serverContentPong))
+				blockUntilClientCloses(conn)
+			})
+			f := &Flow{
+				Model:             &fakeLiveModel{client: client},
+				RequestProcessors: []func(ctx agent.InvocationContext, req *model.LLMRequest, f *Flow) iter.Seq2[*session.Event, error]{liveConfigProcessor},
+				Tools: []tool.Tool{
+					&mockFunctionTool{name: "slow_job", runFunc: func(agent.Context, map[string]any) (map[string]any, error) {
+						time.Sleep(300 * time.Millisecond)
+						return map[string]any{"ok": true}, nil
+					}},
+				},
+				reconnect: testLiveReconnectPolicy(4, 20),
+			}
+			ctx, cancel := newLiveInvocationContext(t)
+			defer cancel()
+			sess, seq, err := f.RunLive(ctx)
+			if err != nil {
+				t.Fatalf("RunLive: %v", err)
+			}
+			var streamErr error
+			sawPong := make(chan struct{})
+			done := make(chan struct{})
+			go func() {
+				defer close(done)
+				once := false
+				for ev, err := range seq {
+					if err != nil && streamErr == nil {
+						streamErr = err
+					}
+					if ev != nil && ev.LLMResponse.Content != nil && !once {
+						for _, p := range ev.LLMResponse.Content.Parts {
+							if p.Text == "pong" {
+								once = true
+								close(sawPong)
+							}
+						}
+					}
+				}
+			}()
+			select {
+			case <-sawPong:
+			case <-time.After(5 * time.Second):
+				t.Error("model turn after the drop was never served")
+			}
+			_ = sess.Close()
+			<-done
+			if streamErr != nil {
+				t.Errorf("session ended with error: %v", streamErr)
+			}
+			if !toolResponseOnConn2.Load() {
+				t.Error("function response was not delivered on the reconnected connection")
+			}
+		})
+	}
+}
