+// limitations under the License.
+
+package llminternal
+
+import (
+	"iter"
+	"strings"
+	"sync/atomic"
+	"testing"
+	"time"
+
+	"github.com/gorilla/websocket"
+
+	"google.golang.org/adk/v2/agent"
+	"google.golang.org/adk/v2/model"
+	"google.golang.org/adk/v2/session"
+	"google.golang.org/adk/v2/tool"
+)
+
+// TestRunLive_AnsweredToolResponseNotResent checks that a response the model
+// answered before a drop is not sent again on the next connection.
+func TestRunLive_AnsweredToolResponseNotResent(t *testing.T) {
+	const toolCall = `{"toolCall":{"functionCalls":[{"id":"c1","name":"slow_job","args":{}}]}}`
+	var conn2Done, conn3Reached, resentOn3 atomic.Bool
+	client, _ := startFakeLiveServer(t, func(connNum int, conn *websocket.Conn) {
+		switch connNum {
+		case 1:
+			_ = conn.WriteMessage(websocket.TextMessage, []byte(toolCall))
+			_ = conn.SetReadDeadline(time.Now().Add(2 * time.Second))
+			for {
+				_, msg, err := conn.ReadMessage()
+				if err != nil {
+					return
+				}
+				if strings.Contains(string(msg), "slow_job") {
+					break
+				}
+			}
+			_ = conn.WriteMessage(websocket.TextMessage, []byte(serverContentPong))
+		case 2:
+			time.Sleep(100 * time.Millisecond)
+			conn2Done.Store(true)
+		default:
+			conn3Reached.Store(true)
+			_ = conn.SetReadDeadline(time.Now().Add(300 * time.Millisecond))
+			for {
+				_, msg, err := conn.ReadMessage()
+				if err != nil {
+					break
+				}
+				if strings.Contains(string(msg), "slow_job") {
+					resentOn3.Store(true)
+				}
+			}
+			_ = conn.SetReadDeadline(time.Time{})
+			_ = conn.WriteMessage(websocket.TextMessage, []byte(serverContentPong))
+			blockUntilClientCloses(conn)
+		}
+	})
+	f := &Flow{
+		Model:             &fakeLiveModel{client: client},
+		RequestProcessors: []func(ctx agent.InvocationContext, req *model.LLMRequest, f *Flow) iter.Seq2[*session.Event, error]{liveConfigProcessor},
+		Tools: []tool.Tool{
+			&mockFunctionTool{name: "slow_job", runFunc: func(agent.Context, map[string]any) (map[string]any, error) {
+				return map[string]any{"ok": true}, nil
+			}},
+		},
+		reconnect: testLiveReconnectPolicy(4, 20),
+	}
+	ctx, cancel := newLiveInvocationContext(t)
+	defer cancel()
+	sess, seq, err := f.RunLive(ctx)
+	if err != nil {
+		t.Fatalf("RunLive: %v", err)
+	}
+	pongs := 0
+	for ev, err := range seq {
+		if err != nil {
+			t.Fatalf("session ended with error: %v", err)
+		}
+		if ev != nil && ev.LLMResponse.Content != nil {
+			for _, p := range ev.LLMResponse.Content.Parts {
+				if p.Text == "pong" {
+					pongs++
+				}
+			}
+		}
+		if pongs == 2 {
+			break
+		}
+	}
+	_ = sess.Close()
+	if !conn2Done.Load() || !conn3Reached.Load() {
+		t.Fatalf("connections 2 and 3 were not both served: conn2=%v conn3=%v", conn2Done.Load(), conn3Reached.Load())
+	}
+	if resentOn3.Load() {
+		t.Error("answered function response was sent again after reconnect")
+	}
+}
+
+// TestRunLive_ReceivedToolResponseResentWhenUnanswered pins the duplicate
+// tradeoff: a response the server read but never answered is sent again after
+// a drop, because the client cannot tell whether the server kept it.
+func TestRunLive_ReceivedToolResponseResentWhenUnanswered(t *testing.T) {
+	const toolCall = `{"toolCall":{"functionCalls":[{"id":"c1","name":"slow_job","args":{}}]}}`
+	var resentOn2 atomic.Bool
+	client, connCount := startFakeLiveServer(t, func(connNum int, conn *websocket.Conn) {
+		if connNum == 1 {
+			_ = conn.WriteMessage(websocket.TextMessage, []byte(toolCall))
+			_ = conn.SetReadDeadline(time.Now().Add(2 * time.Second))
+			for {
+				_, msg, err := conn.ReadMessage()
+				if err != nil || strings.Contains(string(msg), "slow_job") {
+					return
+				}
+			}
+		}
+		_ = conn.SetReadDeadline(time.Now().Add(2 * time.Second))
+		for {
+			_, msg, err := conn.ReadMessage()
+			if err != nil {
+				return
+			}
+			if strings.Contains(string(msg), "slow_job") {
+				resentOn2.Store(true)
+				break
+			}
+		}
+		_ = conn.SetReadDeadline(time.Time{})
+		_ = conn.WriteMessage(websocket.TextMessage, []byte(serverContentPong))
+		blockUntilClientCloses(conn)
+	})
+	f := &Flow{
+		Model:             &fakeLiveModel{client: client},
+		RequestProcessors: []func(ctx agent.InvocationContext, req *model.LLMRequest, f *Flow) iter.Seq2[*session.Event, error]{liveConfigProcessor},
+		Tools: []tool.Tool{
+			&mockFunctionTool{name: "slow_job", runFunc: func(agent.Context, map[string]any) (map[string]any, error) {
+				return map[string]any{"ok": true}, nil
+			}},
+		},
+		reconnect: testLiveReconnectPolicy(4, 20),
+	}
+	ctx, cancel := newLiveInvocationContext(t)
+	defer cancel()
+	sess, seq, err := f.RunLive(ctx)
+	if err != nil {
+		t.Fatalf("RunLive: %v", err)
+	}
+	for ev, err := range seq {
+		if err != nil {
+			t.Fatalf("session ended with error: %v", err)
+		}
+		if ev != nil && ev.LLMResponse.TurnComplete {
+			break
+		}
+	}
+	_ = sess.Close()
+	if connCount.Load() < 2 || !resentOn2.Load() {
+		t.Errorf("unanswered response not resent: dials=%d resent=%v", connCount.Load(), resentOn2.Load())
+	}
+}

