+// h2cPrefaceLen is the number of bytes net/http peeks at before choosing a
+// protocol when cleartext HTTP/2 is enabled.
+const h2cPrefaceLen = 14
+
+// listen opens the TCP listener. With h2c enabled and a read timeout set, the
+// listener bounds the time a client may take to send the first bytes.
+func (w *webLauncher) listen(addr string) (net.Listener, error) {
+	ln, err := net.Listen("tcp", addr)
+	if err != nil {
+		return nil, err
+	}
+	if w.config.useH2C && w.config.readTimeout > 0 {
+		ln = &prefaceDeadlineListener{Listener: ln, timeout: w.config.readTimeout}
+	}
+	return ln, nil
+}
+
+// prefaceDeadlineListener bounds the time a client may take to send the first
+// bytes of a connection. With h2c enabled, net/http blocks peeking for the
+// HTTP/2 preface before any server timeout is armed.
+type prefaceDeadlineListener struct {
+	net.Listener
+	timeout time.Duration
+}
+
+func (l *prefaceDeadlineListener) Accept() (net.Conn, error) {
+	for {
+		c, err := l.Listener.Accept()
+		if err != nil {
+			return nil, err
+		}
+		// A failure here is specific to this connection (e.g. already reset);
+		// returning it would make Serve stop the whole listener.
+		if err := c.SetReadDeadline(time.Now().Add(l.timeout)); err != nil {
+			_ = c.Close()
+			continue
+		}
+		return &prefaceDeadlineConn{Conn: c, remaining: h2cPrefaceLen}, nil
+	}
+}
+
+// prefaceDeadlineConn clears the read deadline once the preface window has
+// been read, so later timeouts are governed by the http.Server.
+type prefaceDeadlineConn struct {
+	net.Conn
+	remaining int
+}
+
+func (c *prefaceDeadlineConn) Read(b []byte) (int, error) {
+	n, err := c.Conn.Read(b)
+	if c.remaining > 0 {
+		c.remaining -= n
+		if c.remaining <= 0 {
+			_ = c.Conn.SetReadDeadline(time.Time{})
+		}
+	}
+	return n, err
+}
+
