+
+type deadlineConn struct {
+	net.Conn
+	reads     [][]byte
+	deadlines []time.Time
+	setErr    error
+	closed    bool
+}
+
+func (c *deadlineConn) Read(b []byte) (int, error) {
+	n := copy(b, c.reads[0])
+	c.reads = c.reads[1:]
+	return n, nil
+}
+
+func (c *deadlineConn) SetReadDeadline(t time.Time) error {
+	if c.setErr != nil {
+		return c.setErr
+	}
+	c.deadlines = append(c.deadlines, t)
+	return nil
+}
+
+func (c *deadlineConn) Close() error {
+	c.closed = true
+	return nil
+}
+
+type queueListener struct {
+	net.Listener
+	conns []net.Conn
+}
+
+func (l *queueListener) Accept() (net.Conn, error) {
+	if len(l.conns) == 0 {
+		return nil, net.ErrClosed
+	}
+	c := l.conns[0]
+	l.conns = l.conns[1:]
+	return c, nil
+}
+
+func TestPrefaceDeadlineListenerAccept(t *testing.T) {
+	const timeout = time.Minute
+	bad := &deadlineConn{setErr: errors.New("reset")}
+	good := &deadlineConn{reads: [][]byte{make([]byte, 8), make([]byte, 6)}}
+	ln := &prefaceDeadlineListener{Listener: &queueListener{conns: []net.Conn{bad, good}}, timeout: timeout}
+
+	before := time.Now()
+	c, err := ln.Accept()
+	if err != nil {
+		t.Fatalf("Accept() error = %v, want the failing connection skipped", err)
+	}
+	if !bad.closed {
+		t.Error("connection whose deadline could not be set was not closed")
+	}
+	if len(good.deadlines) != 1 || good.deadlines[0].Before(before.Add(timeout)) || good.deadlines[0].After(time.Now().Add(timeout)) {
+		t.Fatalf("deadlines after Accept = %v, want one about now+%v", good.deadlines, timeout)
+	}
+
+	buf := make([]byte, 16)
+	if _, err := c.Read(buf); err != nil {
+		t.Fatal(err)
+	}
+	if len(good.deadlines) != 1 {
+		t.Errorf("deadline changed after 8 of %d preface bytes: %v", h2cPrefaceLen, good.deadlines)
+	}
+	if _, err := c.Read(buf); err != nil {
+		t.Fatal(err)
+	}
+	if len(good.deadlines) != 2 || !good.deadlines[1].IsZero() {
+		t.Errorf("deadlines after preface = %v, want the last cleared", good.deadlines)
+	}
+}
+
+func TestListenPrefaceDeadline(t *testing.T) {
+	for _, tc := range []struct {
+		name    string
+		h2c     bool
+		timeout time.Duration
+		wrapped bool
+	}{
+		{name: "h2c with read timeout", h2c: true, timeout: time.Second, wrapped: true},
+		{name: "h2c without read timeout", h2c: true},
+		{name: "http1 only", timeout: time.Second},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			w := NewLauncher().(*webLauncher)
+			w.config.useH2C = tc.h2c
+			w.config.readTimeout = tc.timeout
+			ln, err := w.listen("127.0.0.1:0")
+			if err != nil {
+				t.Fatal(err)
+			}
+			defer ln.Close()
+			if _, wrapped := ln.(*prefaceDeadlineListener); wrapped != tc.wrapped {
+				t.Errorf("listener wrapped = %v, want %v", wrapped, tc.wrapped)
+			}
+		})
+	}
+}

