+// isBodyReadNetError reports whether err is a transport failure from reading the
+// body of a 2xx response. The status check keeps pre-header failures, which the
+// SDK retry loop already handles, out of this recovery; context errors are
+// excluded so an expired deadline is never replayed.
+func isBodyReadNetError(err error, resp *http.Response) bool {
+	if err == nil || resp == nil || resp.StatusCode < 200 || resp.StatusCode > 299 {
