+// resetServer answers every request with 200 headers and a partial body, then
+// resets the connection, except that requests numbered after okAfter get the
+// full body.
+func resetServer(t *testing.T, okAfter int32) (string, *atomic.Int32) {
+	t.Helper()
+	ln, err := net.Listen("tcp", "127.0.0.1:0")
+	if err != nil {
+		t.Fatal(err)
+	}
+	t.Cleanup(func() { _ = ln.Close() })
+	var requests atomic.Int32
+	go func() {
+		for {
+			conn, err := ln.Accept()
+			if err != nil {
+				return
+			}
+			go func(conn net.Conn) {
+				defer conn.Close()
+				req, err := http.ReadRequest(bufio.NewReader(conn))
+				if err != nil {
+					return
+				}
+				_, _ = io.Copy(io.Discard, req.Body)
+				fmt.Fprintf(conn, "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: %d\r\n\r\n", len(openAIOKBody))
+				if requests.Add(1) > okAfter {
+					_, _ = fmt.Fprint(conn, openAIOKBody)
+					return
+				}
+				_, _ = fmt.Fprint(conn, openAIOKBody[:20])
+				time.Sleep(100 * time.Millisecond)
+				_ = conn.(*net.TCPConn).SetLinger(0)
+			}(conn)
+		}
+	}()
+	return "http://" + ln.Addr().String(), &requests
+}
+
+func TestBoundaryRecoversConnectionResetAfterHeaders(t *testing.T) {
+	url, requests := resetServer(t, 1)
+	c := NewRetryCollector()
+	m := testMeta()
+	if _, err := ping(metaCtx(m), openAIClient(url, c, nil)); err != nil {
+		t.Fatalf("CompletionsWithCtx: %v, want the reset body read to be re-sent once", err)
+	}
+	if n := requests.Load(); n != 2 {
+		t.Errorf("requests = %d, want 2", n)
+	}
+	got := attemptsFor(t, c, m)
+	if len(got) != 2 {
+		t.Fatalf("got %d attempts, want 2", len(got))
+	}
+	if got[0].Outcome != AttemptError || got[0].ErrorClass != ErrorClassNetwork || got[0].FailurePhase != FailurePhaseResponseDecode {
+		t.Errorf("attempt 1 = %s %s/%s, want error network/response_decode",
+			got[0].Outcome, got[0].ErrorClass, got[0].FailurePhase)
+	}
+	if got[1].Outcome != AttemptSuccess {
+		t.Errorf("attempt 2 = %+v, want success", got[1])
+	}
+	if req := freezeOne(t, c); req.Outcome != OutcomeRecovered {
+		t.Errorf("outcome = %s, want recovered", req.Outcome)
+	}
+}
+
+func TestBoundaryRecordsSecondConnectionResetAsError(t *testing.T) {
+	url, requests := resetServer(t, 2)
+	c := NewRetryCollector()
+	m := testMeta()
+	if _, err := ping(metaCtx(m), openAIClient(url, c, nil)); err == nil {
+		t.Fatal("CompletionsWithCtx succeeded, want the second reset to fail")
+	}
+	if n := requests.Load(); n != 2 {
+		t.Errorf("requests = %d, want exactly 2 (one re-send)", n)
+	}
+	got := attemptsFor(t, c, m)
+	if len(got) != 2 {
+		t.Fatalf("got %d attempts, want 2", len(got))
+	}
+	for i, a := range got {
+		if a.Outcome != AttemptError || a.ErrorClass != ErrorClassNetwork || a.FailurePhase != FailurePhaseResponseDecode {
+			t.Errorf("attempt %d = %s %s/%s, want error network/response_decode",
+				i+1, a.Outcome, a.ErrorClass, a.FailurePhase)
+		}
+	}
+	if req := freezeOne(t, c); req.Outcome != OutcomeFailed {
+		t.Errorf("outcome = %s, want failed", req.Outcome)
+	}
+}
+
+func TestClassifyBoundaryErrorNetOpError(t *testing.T) {
+	opErr := &net.OpError{Op: "read", Net: "tcp", Err: errors.New("connection reset by peer")}
+	class, phase, ok := classifyBoundaryError(fmt.Errorf("error reading response body: %w", opErr))
+	if !ok || class != ErrorClassNetwork || phase != FailurePhaseResponseDecode {
+		t.Errorf("got %s/%s ok=%v, want network/response_decode", class, phase, ok)
+	}
+	timeoutErr := &net.OpError{Op: "read", Net: "tcp", Err: context.DeadlineExceeded}
+	class, phase, ok = classifyBoundaryError(timeoutErr)
+	if !ok || class != ErrorClassTimeout || phase != FailurePhaseContext {
+		t.Errorf("deadline in OpError: got %s/%s ok=%v, want timeout/context", class, phase, ok)
+	}
+}

