+// HarnessExcludedBy names what excludes a store: the exclude file's
+// `harness:` line when there is one, DEJA_EXCLUDE_HARNESSES otherwise.
+func HarnessExcludedBy(name string) string {
+	name = strings.ToLower(name)
+	for _, pattern := range ExclusionPatterns() {
+		if !strings.HasPrefix(pattern, harnessExcludePrefix) {
+			continue
+		}
+		if strings.TrimSpace(strings.TrimPrefix(pattern, harnessExcludePrefix)) == name {
+			return "`harness:" + name + "` is in " + ExcludePath()
