+// DiagState is a copy of every ingest counter, for a write that must not
+// consume them before the pass that read them is done.
+type DiagState struct {
+	malformed map[string]int
+	failed    map[string]string
+	reasons   map[string]string
+	records   map[string]map[string]string
+	zstd      map[string]bool
+}
+
+// DiagSave copies the counters without clearing them.
+func DiagSave() DiagState {
+	diagMu.Lock()
+	defer diagMu.Unlock()
+	st := DiagState{
+		malformed: maps.Clone(diagMalformed),
+		failed:    maps.Clone(diagFailed),
+		reasons:   maps.Clone(diagReasons),
+		records:   make(map[string]map[string]string, len(diagRecords)),
+		zstd:      maps.Clone(diagZstdMissing),
+	}
+	for p, recs := range diagRecords {
+		st.records[p] = maps.Clone(recs)
+	}
+	return st
+}
+
+// DiagRestore replaces the counters with a state taken by DiagSave.
+func DiagRestore(st DiagState) {
+	diagMu.Lock()
+	defer diagMu.Unlock()
+	diagMalformed, diagFailed = st.malformed, st.failed
+	diagReasons, diagRecords, diagZstdMissing = st.reasons, st.records, st.zstd
+}
+
 // DiagMalformedCounts returns the malformed-line counts accumulated so far
 // without clearing them. The index narrates each store as it lands, which is
 // before the manifest fold that drains these counters (#1993).
